import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {
    static int N, Q;
        static int[] dx = {0, 1, 0, -1};
            static int[] dy = {1, 0, -1, 0};
                static char[][] map;
                    static int[][][] dist;

                        public static void main(String[] args) throws Exception {
                                BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

                                        N = Integer.parseInt(br.readLine().trim());
                                                map = new char[N + 1][N + 1];
                                                        dist = new int[N + 1][N + 1][6];

                                                                for (int i = 1; i <= N; i++) {
                                                                            String str = br.readLine().trim();

                                                                                        for (int j = 1; j <= N; j++) {
                                                                                                        map[i][j] = str.charAt(j - 1);
                                                                                                                    }
                                                                                                                            }

                                                                                                                                    Q = Integer.parseInt(br.readLine().trim());
                                                                                                                                            StringBuilder sb = new StringBuilder();

                                                                                                                                                    for (int q = 0; q < Q; q++) {
                                                                                                                                                                StringTokenizer st = new StringTokenizer(br.readLine());

                                                                                                                                                                            int sx = Integer.parseInt(st.nextToken());
                                                                                                                                                                                        int sy = Integer.parseInt(st.nextToken());
                                                                                                                                                                                                    int ex = Integer.parseInt(st.nextToken());
                                                                                                                                                                                                                int ey = Integer.parseInt(st.nextToken());

                                                                                                                                                                                                                            sb.append(dijkstra(sx, sy, ex, ey)).append('\n');
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                            System.out.print(sb);
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                    static int dijkstra(int sx, int sy, int ex, int ey) {
                                                                                                                                                                                                                                                            for (int i = 1; i <= N; i++) {
                                                                                                                                                                                                                                                                        for (int j = 1; j <= N; j++) {
                                                                                                                                                                                                                                                                                        Arrays.fill(dist[i][j], Integer.MAX_VALUE);
                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                    PriorityQueue<Node> pq = new PriorityQueue<>();

                                                                                                                                                                                                                                                                                                                            dist[sx][sy][1] = 0;
                                                                                                                                                                                                                                                                                                                                    pq.offer(new Node(sx, sy, 1, 0));

                                                                                                                                                                                                                                                                                                                                            while (!pq.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                        Node cur = pq.poll();

                                                                                                                                                                                                                                                                                                                                                                    if (cur.time != dist[cur.x][cur.y][cur.jump]) {
                                                                                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                            if (cur.x == ex && cur.y == ey) {
                                                                                                                                                                                                                                                                                                                                                                                                                            return cur.time;
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    int x = cur.x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                int y = cur.y;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int k = cur.jump;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int time = cur.time;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (k < 5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int nextJump = k + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int nextTime = time + nextJump * nextJump;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (nextTime < dist[x][y][nextJump]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dist[x][y][nextJump] = nextTime;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pq.offer(new Node(x, y, nextJump, nextTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int nextJump = 1; nextJump < k; nextJump++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int nextTime = time + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (nextTime < dist[x][y][nextJump]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dist[x][y][nextJump] = nextTime;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pq.offer(new Node(x, y, nextJump, nextTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int d = 0; d < 4; d++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int nx = x + dx[d] * k;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int ny = y + dy[d] * k;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (nx < 1 || nx > N || ny < 1 || ny > N) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        boolean blocked = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int step = 1; step <= k; step++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int tx = x + dx[d] * step;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int ty = y + dy[d] * step;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (map[tx][ty] == '#') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            blocked = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (blocked || map[nx][ny] != '.') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int nextTime = time + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (nextTime < dist[nx][ny][k]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dist[nx][ny][k] = nextTime;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pq.offer(new Node(nx, ny, k, nextTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        static class Node implements Comparable<Node> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int x, y, jump, time;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Node(int x, int y, int jump, int time) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    this.x = x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.y = y;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            this.jump = jump;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.time = time;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public int compareTo(Node other) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Integer.compare(time, other.time);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }